import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 008: Local-First AI & Authentication Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/008-local-auth-and-ollama.md","filePath":"adr/008-local-auth-and-ollama.md"}'),i={name:"adr/008-local-auth-and-ollama.md"};function r(s,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-008-local-first-ai-authentication-strategy" tabindex="-1">ADR 008: Local-First AI &amp; Authentication Strategy <a class="header-anchor" href="#adr-008-local-first-ai-authentication-strategy" aria-label="Permalink to &quot;ADR 008: Local-First AI &amp; Authentication Strategy&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Superseded by <a href="./012-cloud-pivot-render-turso.html">ADR 012</a> and <a href="./013-ai-logic-refinements.html">ADR 013</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The project initially relied on OpenAI for tender analysis and lacked a user authentication system.</p><ul><li><strong>Cost/Privacy</strong>: Using OpenAI requires API keys and sending sensitive tender data to external servers.</li><li><strong>User Identity</strong>: There was no way to segregate data between users or save progress.</li><li><strong>Developer Experience</strong>: External dependencies (API quotas) caused friction during development/testing.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to move to a <strong>Local-First</strong> architecture for Phase 11.</p><ol><li><p><strong>Local AI (Ollama)</strong>:</p><ul><li>Replaced <code>OpenAIModelService</code> with <code>OllamaModelService</code>.</li><li>Uses <code>llama3</code> (or lightweight equivalents) running locally via Ollama.</li><li><strong>Pros</strong>: Zero cost, privacy-preserving (data never leaves machine), no rate limits.</li><li><strong>Cons</strong>: Requires local hardware resources (RAM/CPU).</li><li><strong>Mitigation</strong>: Implemented input text truncation (4k chars) and strict &quot;JSON-only&quot; prompts to prevent freezing/hallucinations.</li></ul></li><li><p><strong>JWT Authentication</strong>:</p><ul><li>Implemented <code>AuthService</code> using <code>bcrypt</code> (hashing) and <code>jsonwebtoken</code> (session).</li><li>Frontend stores JWT in <code>localStorage</code>.</li><li><strong>Data Persistence</strong>: Currently using <code>InMemoryUserRepository</code> for MVP speed (resets on restart).</li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>: The app is now fully self-contained and free to run. Developers can test indefinitely without costs.</li><li><strong>Negative</strong>: &quot;Mock Mode&quot; is less central now (Ollama is the primary), but fallback logic is still preserved for robustness.</li><li><strong>Risk</strong>: Local models (Llama 3 8B) are less smart than GPT-4o. We implemented heuristic post-processing (e.g., keyword detection for &quot;Optional&quot; requirements) to compensate for lower reasoning capabilities.</li></ul><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h2><ul><li><strong>Dependency Replaced</strong>: <code>openai</code> -&gt; <code>ollama</code></li><li><strong>New Dependency</strong>: <code>bcrypt</code>, <code>jsonwebtoken</code></li><li><strong>Infrastructure</strong>: Backend now requires a running Ollama instance on port 11434.</li></ul>',13)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
